INSERT OR REPLACE INTO products ("id", "title", "slug", "tagline", "description", "fabric_details", "care_instructions", "fit", "price", "compare_at_price", "category_id", "is_featured", "is_new", "is_bestseller", "rating", "reviews_count", "created_at") VALUES ('prod-supima-crew-classic', 'The Sovereign Supima Crew Neck', 'sovereign-supima-crew-neck', '100% Extra-Long Staple American Supima® Cotton', 'Engineered for connoisseurs of understated luxury. Crafted from rare, 100% American Supima® cotton, this tee offers a peerless featherlight drape, silk-like luster, and remarkable color retention through countless washes. Finished with our signature anti-curl neckline and discreet gold-threaded bar tacks.', '100% Extra-Long Staple American Supima Cotton (180 GSM). Double-dyed for color depth. Pre-shrunk bio-wash.', 'Machine wash cold with like colours on delicate cycle. Lay flat to dry in shade. Warm iron if desired.', 'Tailored Fit', 1899, 2499, 'cat-crew-neck', 1, 1, 1, 4.9, 86, '2026-09-07 17:01:18');
INSERT OR REPLACE INTO products ("id", "title", "slug", "tagline", "description", "fabric_details", "care_instructions", "fit", "price", "compare_at_price", "category_id", "is_featured", "is_new", "is_bestseller", "rating", "reviews_count", "created_at") VALUES ('prod-royal-mercerized-polo', 'The Regal Mercerized Piqué Polo', 'regal-mercerized-pique-polo', 'Double-Mercerized Giza 88 Egyptian Cotton', 'Inspired by the refined courts of St. James. Cut from legendary Giza 88 long-staple yarn and treated to a dual mercerization process that imparts a subtle silky sheen, crisp hand-feel, and enduring structural fidelity. Features genuine Australian mother-of-pearl buttons and a non-rolling shirt-style collar.', '100% Mercerized Giza 88 Egyptian Cotton Piqué (220 GSM). Genuine Trochus shell buttons.', 'Hand wash or gentle cold cycle with wool-safe detergent. Steam press lightly on reverse side.', 'Slim Tailored', 2999, 3899, 'cat-polos', 1, 1, 1, 4.95, 112, '2026-09-07 17:01:18');
INSERT OR REPLACE INTO products ("id", "title", "slug", "tagline", "description", "fabric_details", "care_instructions", "fit", "price", "compare_at_price", "category_id", "is_featured", "is_new", "is_bestseller", "rating", "reviews_count", "created_at") VALUES ('prod-mercerized-grandad-henley', 'The Aristocrat Mercerized Henley', 'aristocrat-mercerized-henley', '4-Button Shell Placket with Silk Trim', 'Bridging aristocratic heritage and off-duty leisure. Spun from 60s count compact combed cotton, featuring a four-button concealed placket with Italian silk piping on the inner band. The sleeves are finished with 1x1 French cuffs that hug the forearm gracefully.', '95% Mercerized Egyptian Cotton, 5% Elastane for movement (210 GSM). Custom dyed pearl buttons.', 'Wash on delicate cycle inside out. Do not tumble dry. Reshape while damp.', 'Custom Fit', 2499, 3299, 'cat-henleys', 1, 0, 1, 4.88, 64, '2026-09-07 17:01:18');
INSERT OR REPLACE INTO products ("id", "title", "slug", "tagline", "description", "fabric_details", "care_instructions", "fit", "price", "compare_at_price", "category_id", "is_featured", "is_new", "is_bestseller", "rating", "reviews_count", "created_at") VALUES ('prod-heavyweight-oversized-tee', 'The Minimalist Atelier Heavyweight Tee', 'minimalist-atelier-heavyweight-tee', '280 GSM Structured Compact Cotton', 'The definitive contemporary luxury silhouette. Cut with architectural drop-shoulders and a boxy yet flattering drape. Knitted at 280 GSM, this garment holds its sculptural form without clinging, offering complete opacity and effortless sartorial confidence.', '100% Compact Organic Combed Cotton (280 GSM Heavyweight). Pre-washed with silicone softening.', 'Machine wash cold. Turn inside out. Flat air dry. Do not bleach.', 'Relaxed Boxy Fit', 2199, 2799, 'cat-oversized', 1, 1, 0, 4.82, 47, '2026-09-07 17:01:18');
INSERT OR REPLACE INTO products ("id", "title", "slug", "tagline", "description", "fabric_details", "care_instructions", "fit", "price", "compare_at_price", "category_id", "is_featured", "is_new", "is_bestseller", "rating", "reviews_count", "created_at") VALUES ('prod-textured-jacquard-knit-tee', 'The Florentine Textured Jacquard Knit', 'florentine-textured-jacquard-knit', 'Micro-Waffle Geometric Weave', 'An homage to classic Italian resortwear. Knitted with an intricate dimensional waffle microstructure that encourages airflow while bestowing rich visual interest. Styled effortlessly under an unconstructed blazer or paired with tailored linen trousers.', '100% Mercerized Combed Long-Staple Cotton (230 GSM). Breathable micro-honeycomb knit.', 'Gentle machine wash in washbag. Dry flat. Do not wring or tumble dry.', 'Regular European Fit', 2799, 3499, 'cat-crew-neck', 0, 1, 0, 4.91, 38, '2026-09-07 17:01:18');
INSERT OR REPLACE INTO products ("id", "title", "slug", "tagline", "description", "fabric_details", "care_instructions", "fit", "price", "compare_at_price", "category_id", "is_featured", "is_new", "is_bestseller", "rating", "reviews_count", "created_at") VALUES ('prod-tipping-collar-luxe-polo', 'The Monogram Contrast-Tip Polo', 'monogram-contrast-tip-polo', 'Subtle Gold Tipped Knit Collar & Cuffs', 'The gold standard of country club panache. Detailed with a contrast champagne-gold tipping along the ribbed collar and sleeve cuffs. Fastened with bespoke metallic-rimmed buttons and finished with side vents bound in grosgrain ribbon.', '96% Supima Cotton, 4% Lycra (200 GSM). Contrast mercerized collar ribbing.', 'Cold delicate wash. Iron inside out to protect tipping detail.', 'Athletic Tailored', 2599, 3199, 'cat-polos', 1, 0, 1, 4.89, 73, '2026-09-07 17:01:18');
INSERT OR REPLACE INTO products ("id", "title", "slug", "tagline", "description", "fabric_details", "care_instructions", "fit", "price", "compare_at_price", "category_id", "is_featured", "is_new", "is_bestseller", "rating", "reviews_count", "created_at") VALUES ('prod-sea-island-heritage-crew', 'The Sovereign Sea Island Heritage Crew', 'sovereign-sea-island-heritage-crew', 'Spun from Rare West Indian Sea Island Certified Cotton', 'The pinnacle of textile provenance. Cultivated in the Caribbean microclimates, West Indian Sea Island cotton represents less than 0.0004% of global production. Silky to the touch with unrivaled staple length and tensile strength, handcrafted with blind-stitched hems.', '100% Certified West Indian Sea Island Cotton (170 GSM). Featherlight luxury single jersey.', 'Hand wash cool or dry clean recommended. Lay flat in shade. Cool iron with cloth.', 'Tailored European Fit', 3499, 4499, 'cat-crew-neck', 1, 1, 0, 4.97, 51, '2026-09-07 17:01:18');
INSERT OR REPLACE INTO products ("id", "title", "slug", "tagline", "description", "fabric_details", "care_instructions", "fit", "price", "compare_at_price", "category_id", "is_featured", "is_new", "is_bestseller", "rating", "reviews_count", "created_at") VALUES ('prod-monaco-grand-prix-polo', 'The Riviera Monaco Knit Polo', 'riviera-monaco-knit-polo', 'Open-Collar Resort Knit with Saddle-Stitch Shoulders', 'Designed for Mediterranean afternoons and yacht club terraces. Features an Italian open Johnny collar without buttons, offering effortless nonchalance. Knitted from 2-ply long-staple combed cotton with subtle ribbed borders.', '100% Giza Long-Staple Combed Cotton (210 GSM). Breathable open-stitch knit.', 'Cold gentle cycle inside a washbag. Dry flat. Never tumble dry.', 'Relaxed Tailored', 3199, 3999, 'cat-polos', 1, 1, 1, 4.93, 79, '2026-09-07 17:01:18');
INSERT OR REPLACE INTO products ("id", "title", "slug", "tagline", "description", "fabric_details", "care_instructions", "fit", "price", "compare_at_price", "category_id", "is_featured", "is_new", "is_bestseller", "rating", "reviews_count", "created_at") VALUES ('prod-ottoman-ribbed-textured-tee', 'The Ottoman Ribbed Architectural Tee', 'ottoman-ribbed-architectural-tee', 'Horizontal Raised Ottoman Cord Structure', 'A triumph of tactile textile architecture. Constructed with prominent horizontal ribs that drape with resolute structure while resisting wrinkling. Accented with twin-needle reinforced necklines and vented side splits.', '97% Combed Compact Cotton, 3% Elastane (260 GSM Heavyweight).', 'Machine wash cold inside out. Flat air dry. Reshape while wet.', 'Structured Regular', 2699, 3399, 'cat-crew-neck', 0, 1, 1, 4.86, 42, '2026-09-07 17:01:18');
INSERT OR REPLACE INTO products ("id", "title", "slug", "tagline", "description", "fabric_details", "care_instructions", "fit", "price", "compare_at_price", "category_id", "is_featured", "is_new", "is_bestseller", "rating", "reviews_count", "created_at") VALUES ('prod-artisanal-indigo-slub-tee', 'The Kyoto Indigo Slub Artisan Tee', 'kyoto-indigo-slub-artisan-tee', 'Rope-Dyed Natural Plant Indigo with Variable Slub Texture', 'Imbued with Japanese wabi-sabi aesthetics. Spun with deliberate slub yarns that yield an organic, textured grain. Hand rope-dyed in authentic botanical indigo baths, this garment patinas gracefully with every wear, telling your unique sartorial story.', '100% Slub-Spun Organic Cotton (200 GSM). Plant indigo dip-dyed.', 'Wash separately in cold water. Indigo may transfer during early wear. Air dry.', 'Relaxed Classic Fit', 2899, 3699, 'cat-crew-neck', 1, 1, 0, 4.9, 36, '2026-09-07 17:01:18');
INSERT OR REPLACE INTO products ("id", "title", "slug", "tagline", "description", "fabric_details", "care_instructions", "fit", "price", "compare_at_price", "category_id", "is_featured", "is_new", "is_bestseller", "rating", "reviews_count", "created_at") VALUES ('prod-highland-thermal-waffle-henley', 'The Highland Thermal Waffle Henley', 'highland-thermal-waffle-henley', '320 GSM Heavy Waffle Knit with Horn Buttons', 'Engineered for alpine comfort and country estates. Tailored from substantial 320 GSM honeycomb thermal jersey. Complete with genuine polished horn buttons, reinforced shoulder seams, and elongated ribbed cuffs that hold their shape.', '100% Carded Combed Cotton Heavy Honeycomb Waffle (320 GSM). Natural horn buttons.', 'Delicate machine wash cold. Do not tumble dry. Reshape horizontally.', 'Tailored Thermal Fit', 3299, 4199, 'cat-henleys', 0, 1, 1, 4.94, 58, '2026-09-07 17:01:18');
INSERT OR REPLACE INTO products ("id", "title", "slug", "tagline", "description", "fabric_details", "care_instructions", "fit", "price", "compare_at_price", "category_id", "is_featured", "is_new", "is_bestseller", "rating", "reviews_count", "created_at") VALUES ('prod-savile-row-silk-vneck', 'The Mayfair Silk-Cotton V-Neck', 'mayfair-silk-cotton-vneck', '70% Supima Cotton, 30% Mulberry Silk Blend', 'An unhurried study in discreet luxury. Blending lustrous grade-6A Mulberry silk with extra-long staple Supima cotton creates a fabric with exceptional thermodynamic breathability and sublime softness against bare skin. Features a shallow, tasteful V-neckline framed by fine gauge ribbing.', '70% Supima Cotton, 30% Grade-6A Mulberry Silk (165 GSM).', 'Hand wash cool with silk detergent. Dry flat in shade. Iron damp with warm iron.', 'Sartorial Slim Fit', 3699, 4799, 'cat-crew-neck', 1, 0, 1, 4.96, 67, '2026-09-07 17:01:18');
INSERT OR REPLACE INTO products ("id", "title", "slug", "tagline", "description", "fabric_details", "care_instructions", "fit", "price", "compare_at_price", "category_id", "is_featured", "is_new", "is_bestseller", "rating", "reviews_count", "created_at") VALUES ('prod-oversized-heavy-raw-slate-tee', 'The Belgravia Drop-Shoulder Heavy Tee', 'belgravia-drop-shoulder-heavy-tee', '300 GSM Ultra-Structured Carded Cotton', 'The apex of structured architectural streetwear tailoring. Woven with an ultra-dense 300 GSM count that creates sharp architectural drape and zero cling. Styled with clean seamless neck ribbing and drop shoulders.', '100% Raw Heavyweight Compact Cotton (300 GSM). Pre-shrunk silicone finish.', 'Cold wash with gentle cycle. Hang dry or lay flat.', 'Boxy Oversized', 2499, 3199, 'cat-oversized', 0, 1, 0, 4.87, 33, '2026-09-07 17:01:18');
INSERT OR REPLACE INTO products ("id", "title", "slug", "tagline", "description", "fabric_details", "care_instructions", "fit", "price", "compare_at_price", "category_id", "is_featured", "is_new", "is_bestseller", "rating", "reviews_count", "created_at") VALUES ('prod-houndstooth-mercerized-polo', 'The St. James Micro-Houndstooth Polo', 'st-james-micro-houndstooth-polo', 'Jacquard Double-Mercerized Houndstooth Micro-Knit', 'A sartorial masterpiece blending optical geometry with buttery Egyptian yarn. Knitted with an elusive micro-houndstooth jacquard pattern visible only at gentlemanly proximity. Finished with a semi-spread tailored collar and etched shell buttons.', '100% Double-Mercerized Egyptian Cotton (225 GSM). Australian Trochus shell buttons.', 'Hand wash or gentle wool cycle in mesh bag. Lay flat to dry.', 'Tailored Royal Fit', 3399, 4299, 'cat-polos', 1, 1, 1, 4.95, 61, '2026-09-07 17:01:18');
INSERT OR REPLACE INTO products ("id", "title", "slug", "tagline", "description", "fabric_details", "care_instructions", "fit", "price", "compare_at_price", "category_id", "is_featured", "is_new", "is_bestseller", "rating", "reviews_count", "created_at") VALUES ('prod-bauhaus-monogram-tee', 'The Bauhaus Architectural Monogram Tee', 'bauhaus-architectural-monogram-tee', '240 GSM Structured Heavy Jersey with Debossed Chest Motif', 'An homage to modern structural minimalism. Sculpted from 240 GSM combed organic cotton with an architectural geometric deboss on the left chest. Engineered with drop shoulders and a firm high-gauge neckline that maintains its pristine geometric contour throughout wear.', '100% Combed Organic Cotton (240 GSM). High-gauge compact spin for minimal pill. Micro-ribbed 1.25-inch collar.', 'Reverse wash on gentle cold cycle. Reshape while damp. Do not tumble dry. Low steam iron on reverse.', 'Relaxed Boxy Fit', 2199, 2899, 'cat-graphic-art', 1, 1, 0, 4.9, 38, '2026-09-08 11:14:12');
INSERT OR REPLACE INTO products ("id", "title", "slug", "tagline", "description", "fabric_details", "care_instructions", "fit", "price", "compare_at_price", "category_id", "is_featured", "is_new", "is_bestseller", "rating", "reviews_count", "created_at") VALUES ('prod-abstract-linear-tee', 'The Abstract Atelier Linear Graphic Tee', 'abstract-atelier-linear-graphic-tee', 'Japanese High-Density Pigment Screen Print on 220 GSM Jersey', 'An expressive canvas for subtle artistic distinction. Features an archival continuous line drawing developed exclusively in our studio, applied through multi-pass water-based Japanese pigment ink that softens with age without cracking. Cut with clean tailored shoulders and side split hems.', '100% Long-Staple Bio-Washed Cotton (220 GSM). Breathable, water-based non-toxic screen print.', 'Machine wash cold inside out. Tumble dry low or air dry in shade. Do not iron directly on print.', 'Tailored Modern Fit', 1999, 2599, 'cat-graphic-art', 0, 1, 1, 4.8, 42, '2026-09-08 11:14:12');
INSERT OR REPLACE INTO products ("id", "title", "slug", "tagline", "description", "fabric_details", "care_instructions", "fit", "price", "compare_at_price", "category_id", "is_featured", "is_new", "is_bestseller", "rating", "reviews_count", "created_at") VALUES ('prod-biella-pocket-tee', 'The Biella Heavyweight Boxy Pocket Tee', 'biella-heavyweight-boxy-pocket-tee', '280 GSM Structured Compact Cotton with Reinforced Chest Pocket', 'Designed in the spirit of Northern Italian utilitarian elegance. Constructed from an opulent 280 GSM heavyweight compact jersey that drapes with authoritative poise. Accompanied by an angular mitred chest pocket with double-needle edge stitching and twin needle hem finishes.', '100% Compact Organic Cotton (280 GSM). Double-needle reinforcement at stress points. Anti-sag rib collar.', 'Cold wash with mild detergent. Reshape hem while wet. Do not bleach. Cool iron.', 'Boxy Relaxed Cut', 2299, 2999, 'cat-oversized', 1, 1, 0, 4.9, 51, '2026-09-08 11:14:12');
INSERT OR REPLACE INTO products ("id", "title", "slug", "tagline", "description", "fabric_details", "care_instructions", "fit", "price", "compare_at_price", "category_id", "is_featured", "is_new", "is_bestseller", "rating", "reviews_count", "created_at") VALUES ('prod-breton-stripe-tee', 'The Côte d''Azur Nautical Breton Stripe Tee', 'cote-dazur-nautical-breton-stripe-tee', 'Yarn-Dyed 210 GSM Combed Cotton in Authentic French Maritime Ratio', 'The timeless uniform of Riviera royalty. Unlike printed stripes, each band is individually yarn-dyed before weaving on historic circular looms to ensure lifelong contrast sharpness. Finished with a boatneck crew collar and tonal anchor embroidery at the left hip.', '100% Yarn-Dyed Combed Cotton (210 GSM). Pre-washed to prevent diagonal skewing.', 'Cold wash with similar hues. Iron inside out to protect embroidery. Line dry in shaded breeze.', 'Classic European Fit', 2499, 3299, 'cat-crew-neck', 0, 1, 1, 4.85, 67, '2026-09-08 11:14:12');
INSERT OR REPLACE INTO products ("id", "title", "slug", "tagline", "description", "fabric_details", "care_instructions", "fit", "price", "compare_at_price", "category_id", "is_featured", "is_new", "is_bestseller", "rating", "reviews_count", "created_at") VALUES ('prod-milano-mockneck-tee', 'The Milano Ribbed Architectural Mock-Neck T-Shirt', 'milano-ribbed-architectural-mockneck-tee', 'Double-Knit Interlock Cotton with 1.75-Inch Sculpted Mock Collar', 'A commanding hybrid bridging high knitwear and tailored luxury tees. The 1.75-inch mock neck stands autonomously without choking, knitted with 4% elastane memory ribbing. Ideal when layered under bespoke unconstructed blazers or worn solo as a minimalist statement.', '96% Mercerized Long-Staple Cotton, 4% Lycra (250 GSM). Double-knit interlock weave.', 'Machine wash cold delicate. Do not wring. Dry flat on luxury hanger.', 'Sculpted Tailored Fit', 2599, 3499, 'cat-crew-neck', 1, 1, 0, 4.95, 29, '2026-09-08 11:14:12');
INSERT OR REPLACE INTO products ("id", "title", "slug", "tagline", "description", "fabric_details", "care_instructions", "fit", "price", "compare_at_price", "category_id", "is_featured", "is_new", "is_bestseller", "rating", "reviews_count", "created_at") VALUES ('prod-versailles-botanical-tee', 'The Versailles Botanical Archival Graphic Tee', 'versailles-botanical-archival-graphic-tee', 'Historic Engraving Artwork on Mineral Washed 210 GSM Cotton', 'Inspired by 18th-century French royal garden archives. Intricately etched botanical illustrations rendered in sepia tones onto vintage enzyme-treated cotton. Features hand-finished blind stitch hems and distressed inner collar label detailing.', '100% Mineral Enzyme Washed Cotton (210 GSM). Breathable discharge print for zero hand-feel.', 'Wash cold inside out. Flat dry away from direct sunlight. Warm iron on reverse.', 'Vintage Relaxed Fit', 2199, 2799, 'cat-graphic-art', 0, 1, 0, 4.88, 34, '2026-09-08 11:14:12');
INSERT OR REPLACE INTO products ("id", "title", "slug", "tagline", "description", "fabric_details", "care_instructions", "fit", "price", "compare_at_price", "category_id", "is_featured", "is_new", "is_bestseller", "rating", "reviews_count", "created_at") VALUES ('prod-zurich-seamless-tee', 'The Zurich Zero-Torque Seamless T-Shirt', 'zurich-zero-torque-seamless-tee', 'Circular Knit Tubular Cotton with Bonded Ultrasonic Hems', 'Swiss engineering applied to the classic tee. Circular-knitted with zero side seams to eliminate twisting and friction against the skin. Hems are precision bonded using heat-fused ultrasonic tape for an ultra-flat, razor-sharp edge that lies invisibly under garments.', '100% Long-Staple Compact Ring-Spun Cotton (195 GSM). Seamless tubular construction.', 'Gentle machine wash cold. Do not dry clean. Low tumble dry or air dry.', 'Slim Architectural Fit', 2399, 3199, 'cat-crew-neck', 0, 1, 0, 4.92, 47, '2026-09-08 11:14:12');
INSERT OR REPLACE INTO products ("id", "title", "slug", "tagline", "description", "fabric_details", "care_instructions", "fit", "price", "compare_at_price", "category_id", "is_featured", "is_new", "is_bestseller", "rating", "reviews_count", "created_at") VALUES ('prod-custom-bespoke-embroidered-tee', 'The Custom Bespoke Atelier Embroidered Tee', 'custom-bespoke-atelier-embroidered-tee', 'Personal Monogram or Custom Crest Embroidery on American Supima® (Call: 8310246790)', 'Your personal insignia, monogram, or bespoke artwork hand-embroidered by our master needleworkers. Crafted on our flagship 100% American Supima® blank canvas. Minimum order: 1 piece for personal luxury, or small atelier batches. Contact our Concierge directly on +91 8310246790 or WhatsApp to confirm your personalized design, thread shades, and placement.', '100% American Extra-Long Staple Supima Cotton (190 GSM). High-precision Madeira metallic or tonal thread embroidery.', 'Delicate cold wash. Use wash pouch. Iron on reverse of embroidery.', 'Tailored Bespoke Fit', 2699, 3699, 'cat-custom-bespoke', 1, 1, 1, 5, 88, '2026-09-08 11:14:12');
INSERT OR REPLACE INTO products ("id", "title", "slug", "tagline", "description", "fabric_details", "care_instructions", "fit", "price", "compare_at_price", "category_id", "is_featured", "is_new", "is_bestseller", "rating", "reviews_count", "created_at") VALUES ('prod-custom-corporate-heavy-tee', 'The Custom Corporate & Event Heavyweight Boxy Tee', 'custom-corporate-event-heavyweight-boxy-tee', 'Made-to-Order Bulk Studio Orders (10 to 500+ Pcs • Direct WhatsApp: 8310246790)', 'The executive benchmark for company merchandise, luxury retreat uniforms, startup merch, and bespoke private events. Constructed in 240 GSM or 280 GSM heavyweight organic cotton with customizable screen printing, high-density puff printing, or embroidery. Volume tier pricing applied. Contact our Dedicated Corporate Concierge directly at +91 8310246790 or WhatsApp for sample swatches and rapid quotations.', '100% Heavy Combed Cotton (240-280 GSM). Bio-polished and silicone washed for ultra-soft hand feel.', 'Commercial or standard laundry safe. High wash durability tested up to 60 washes.', 'Modern Structured Boxy Fit', 1699, 2499, 'cat-custom-bespoke', 1, 1, 1, 4.98, 114, '2026-09-08 11:14:12');
INSERT OR REPLACE INTO products ("id", "title", "slug", "tagline", "description", "fabric_details", "care_instructions", "fit", "price", "compare_at_price", "category_id", "is_featured", "is_new", "is_bestseller", "rating", "reviews_count", "created_at") VALUES ('prod-verona-washed-oversized-tee', 'The Verona Washed Vintage Oversized Tee', 'verona-washed-vintage-oversized-tee', '300 GSM Heavyweight Stone-Washed Jersey with Distressed Edges', 'A masterclass in effortless drape. Stone-washed for 4 hours with pumice mineral stones to achieve nuanced color fade around seams and necklines. Cut with exaggerated broad shoulders, wide sleeves, and a substantial 300 GSM hand that holds its street-tailored drape.', '100% Heavy Organic French Jersey (300 GSM). Pumice stone enzyme wash. Pre-shrunk.', 'Wash separately in cold water on first wear. Tumble dry delicate. Do not iron collar.', 'Exaggerated Oversized Fit', 2499, 3399, 'cat-oversized', 0, 0, 1, 4.96, 73, '2026-09-10 08:02:44');

